#!/usr/bin/env bash\n\n# Array of whimsical greetings\n_greetings=(\n  \"Hello, wanderer of the wasteland!\"\n  \"Greetings, brave survivor!\"\n  \"Salutations, time traveler!\"\n  \"Hey there, post-apocalyptic pal!\"\n  \"Welcome, fellow explorer!\"\n  \"Yo, chaos coordinator!\"\n  \"Ahoy, anomaly hunter!\"\n  \"Hi, temporal tinkerer!\"\n  \"What's up, rift rider?\"\n  \"Good day, void whisperer!\"\n)\n\n# Pick a random index\n_index=$((RANDOM % ${#_greetings[@]}))\n\n# Output the selected greeting\necho "${_greetings[$_index]}"
